{
  "translate": function(phrase: string): string {
    const vowels = "aeiouAEIOU";
    const consonants = "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ";
    const special = "xr yt";

    const words = phrase.split(" ");
    const result: string[] = [];

    for (const word of words) {
      if (word === "") continue;

      if (special.includes(word[0])) {
        result.push(word.slice(2) + word[0] + "ay");
      } else if (vowels.includes(word[0])) {
        result.push(word + "ay");
      } else {
        let consonantsPart = "";
        let i = 0;
        while (i < word.length && !vowels.includes(word[i])) {
          consonantsPart += word[i];
          i++;
        }
        if (consonantsPart === "") {
          result.push(word + "ay");
        } else {
          result.push(word.slice(i) + consonantsPart + "ay");
        }
      }
    }

    return result.join(" ");
  }
}
